(function(g){'use strict';
const mean=a=>a.reduce((s,v)=>s+v,0)/Math.max(1,a.length),clamp=(v,a,b)=>Math.max(a,Math.min(b,v));
function rng(s){return()=>{s=(Math.imul(1664525,s)+1013904223)>>>0;return s/4294967296}}
function solve(a,b){a=a.map((r,i)=>[...r,b[i]]);for(let j=0;j<b.length;j++){let q=j;for(let k=j+1;k<b.length;k++)if(Math.abs(a[k][j])>Math.abs(a[q][j]))q=k;[a[q],a[j]]=[a[j],a[q]];let v=a[j][j]||1e-9;for(let k=j;k<=b.length;k++)a[j][k]/=v;for(let i=0;i<b.length;i++)if(i!==j){v=a[i][j];for(let k=j;k<=b.length;k++)a[i][k]-=v*a[j][k]}}return a.map(r=>r[b.length])}
function fit(xs,ys){let d=xs[0].length,A=Array.from({length:d},()=>Array(d).fill(0)),b=Array(d).fill(0);xs.forEach((x,i)=>x.forEach((v,j)=>{b[j]+=v*ys[i];x.forEach((w,k)=>A[j][k]+=v*w)}));for(let j=1;j<d;j++)A[j][j]+=.02;return solve(A,b)}
const pred=(m,x)=>m.reduce((s,v,i)=>s+v*x[i],0), rmse=(y,p)=>Math.sqrt(mean(y.map((v,i)=>(v-p[i])**2))),mae=(y,p)=>mean(y.map((v,i)=>Math.abs(v-p[i])));
function knn(xs,ys,x,k=9){const near=xs.map((z,i)=>({i,d:z.reduce((s,v,j)=>s+(v-x[j])**2,0)})).sort((a,b)=>a.d-b.d).slice(0,k);return mean(near.map(n=>ys[n.i]))}
function logistic(xs,ys){let m=Array(xs[0].length).fill(0);for(let z=0;z<220;z++){let grad=m.map(()=>0);xs.forEach((x,i)=>{let e=1/(1+Math.exp(-clamp(pred(m,x),-25,25)))-ys[i];x.forEach((v,j)=>grad[j]+=e*v)});m=m.map((v,j)=>v-.15*(grad[j]/xs.length+.003*(j?v:0)))}return m}
function score(y,p){let tp=0,fp=0,fn=0; y.forEach((v,i)=>{tp+=v&&p[i]?1:0;fp+=!v&&p[i]?1:0;fn+=v&&!p[i]?1:0});return{precision:tp/(tp+fp||1),recall:tp/(tp+fn||1),f1:2*tp/(2*tp+fp+fn||1),tp,fp,fn,n:y.length}}
function series(title,xLabel,yLabel,traces,extra={}){return{title,xLabel,yLabel,traces,...extra}}
function trace(name,values,color){return{name,values,color}}
function pair(a){return a.map((v,i)=>[i,v])}
function metric(label,value,unit=''){return{label,value,unit}}

function simulate(gain,control,target,limit){let x=0,z=0,angle=0,path=[[0,0]],violations=0,commands=[];for(let i=0;i<60;i++){const desired=Math.atan2(target.x-x,Math.max(20,target.z-z)),raw=desired-angle,u=clamp(raw/Math.max(.1,control),-limit,limit);angle+=gain*u;x+=10*Math.sin(angle);z+=10*Math.cos(angle);if(Math.abs(gain*u)>limit*1.01)violations++;path.push([x,z]);commands.push(u)}return{path,violations,error:Math.hypot(x-target.x,z-target.z),commands}}
function execute(gain,commands,target,limit){let x=0,z=0,angle=0,path=[[0,0]],violations=0;commands.forEach(u=>{let delta=gain*u;angle+=delta;if(Math.abs(delta)>limit*1.01)violations++;x+=10*Math.sin(angle);z+=10*Math.cos(angle);path.push([x,z])});return{path,violations,error:Math.hypot(x-target.x,z-target.z),commands}}
function run(p){const r=rng(43),xs=[],ys=[];for(let i=0;i<80;i++){let u=(r()-.5)*.2;xs.push([1,u]);ys.push(.74*u+.002*(r()-.5))}let learned=fit(xs,ys)[1],target={x:p.targetX,z:p.targetZ},limit=p.limit*Math.PI/180/3,best=null,grid=[];for(let aim=-40;aim<=40;aim+=4){let adjusted={x:target.x+aim,z:target.z},plan=simulate(learned,learned,adjusted,limit),terminal=plan.path.at(-1),objective=Math.hypot(terminal[0]-target.x,terminal[1]-target.z)+plan.violations*50;grid.push({aim,objective});if(!best||objective<best.objective)best={aim,objective}}let chosen=simulate(learned,learned,{x:target.x+best.aim,z:target.z},limit),baselinePlan=simulate(1,1,target,limit),actual=execute(p.gain,chosen.commands,target,limit),base=execute(p.gain,baselinePlan.commands,target,limit),markers=[target.x,target.z];return{params:p,metrics:[metric('学习响应路径末端偏差',Math.hypot(actual.path.at(-1)[0]-target.x,actual.path.at(-1)[1]-target.z),'m'),metric('单位增益基线偏差',base.error,'m'),metric('转角约束超限步',actual.violations,'/60')],views:[series('二维井眼轨迹：横向位移与真垂深','横向位移 / m','真垂深 / m',[trace('学习响应后候选',actual.path,'#14796f'),trace('单位增益追踪基线',base.path,'#c07648'),trace('目标点',[[target.x,target.z]],'#b15c70')],{scatterLast:true,depth:true}),series('候选目标补偿：选择动作而非直接画一条线','横向补偿 / m','预测目标偏差 / m',[trace('候选目标函数',grid.map(o=>[o.aim,o.objective]),'#547da0')])],notes:[`用80条独立转向试验估计增益${learned.toFixed(3)}；目标(${target.x},${target.z})m，未来地层增益由滑块设为${p.gain}。`,`60步×10m；每步转角上限${(p.limit/3).toFixed(2)}°，对应${p.limit}°/30m。曲线纵轴向下为井深。`,`先以学习增益比较21个补偿候选，再用用户设置的未来增益推进井眼；目标误差用实际路径末端与原目标距离。`],observations:xs,predictions:actual.path,baseline:base.path,evaluationTruth:{target},training:{gain:learned,count:80},grid,split:'80 steering trials / independent future gain'}}
g.Experiment={run,sceneId:'d3',caseId:'s17x-d3-trajectory-control'};})(globalThis);
